python3 << 'EOF'
import xml.etree.ElementTree as ET

# Check the latest version available
xml_files = [
    "/home/runner/.nuget/packages/microsoft.extensions.ai/10.7.0/lib/net8.0/Microsoft.Extensions.AI.xml",
]

for xml_file in xml_files:
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()

        # Find AITool and AIFunction
        members = root.findall('.//member')

        print("=== AITool ===\n")
        for member in members:
            name = member.get('name', '')
            if 'AITool' in name and name.startswith('T:'):
                summary = member.find('summary')
                print(f"{name}")
                if summary is not None and summary.text:
                    print(f"  {summary.text.strip()[:200]}\n")

        print("\n=== AIFunction ===\n")
        for member in members:
            name = member.get('name', '')
            if 'AIFunction' in name and (name.startswith('T:') or name.startswith('M:Microsoft.Extensions.AI.AIFunctionFactory')):
                summary = member.find('summary')
                print(f"{name}")
                if summary is not None and summary.text:
                    print(f"  {summary.text.strip()[:200]}\n")
                if 'Factory' in name and name.startswith('M:'):
                    break
    except Exception as e:
        print(f"Error with {xml_file}: {e}")
EOF

