    )

====================================================================================================
2. INVOKING THE AGENT
====================================================================================================

NON-STREAMING METHOD:

  public Task<ChatMessageContent> RunAsync(
      string userMessage,
      AgentSession session,
      ChatClientAgentRunOptions? options = null,
      CancellationToken cancellationToken = default
  )

  Alternative signatures also available for ChatMessage input and bulk messages.

STREAMING METHOD:

  public IAsyncEnumerable<ChatMessageContent> RunStreamingAsync(
      string userMessage,
      AgentSession session,
      ChatClientAgentRunOptions? options = null,
      CancellationToken cancellationToken = default
  )

====================================================================================================
3. DEFINING AND REGISTERING TOOLS
====================================================================================================

USING AIFunctionFactory (for creating tool definitions):

  static class AIFunctionFactory
  {
      // Factory method: Create from delegate
      public static AIFunction Create(
          Delegate method,
          AIFunctionFactoryOptions options
      )

      // Factory method: Create from MethodInfo
      public static AIFunction Create(
          MethodInfo method,
          object? target,
          AIFunctionFactoryOptions options
      )

      // Factory method: Create with explicit parameters
      public static AIFunction Create(
          Delegate method,
          string functionName,
          string description,
          JsonSerializerOptions? options = null
      )
  }

AITOOL STRUCTURE (what to pass to agent):

  public class AITool
  {
      public string Name { get; }
      public string Description { get; }
      public IDictionary<string, object?> AdditionalProperties { get; }

      // The AIFunction goes into AdditionalProperties or as a nested type
  }

REGISTERING TOOLS WITH AGENT:

  // Option 1: In constructor
  var tools = new List<AITool> { tool1, tool2 };
  var agent = new ChatClientAgent(
      chatClient,
      instructions,
      tools: tools
  );

  // Option 2: Via ChatOptions in ChatClientAgentRunOptions
  var runOptions = new ChatClientAgentRunOptions
  {
