====================================================================================================

Add these using statements:
  using Microsoft.Agents.AI;
  using Microsoft.Extensions.AI;
  using Microsoft.Extensions.Logging;
  using System.Collections.Generic;
  using System.Text.Json;

====================================================================================================
7. TYPICAL CONSOLE APP FLOW
====================================================================================================

  // 1. Set up logging
  ILoggerFactory loggerFactory = LoggerFactory.Create(builder => builder.AddConsole());

  // 2. Create IChatClient (e.g., from OpenAI)
  var client = new OpenAIClient(apiKey);
  IChatClient chatClient = client.AsChatClient("gpt-4");

  // 3. Define tools/functions
  var toolFunction = AIFunctionFactory.Create(
      MyToolMethod,
      "get_weather",
      "Gets the current weather"
  );
  var tools = new List<AITool> { new AITool { ... } };

  // 4. Create agent
  var agent = new ChatClientAgent(
      chatClient,
      instructions: "You are a helpful assistant.",
      tools: tools,
      loggerFactory: loggerFactory
  );

  // 5. Create session
  var session = await agent.CreateSessionAsync();

  // 6. Invoke agent
  var result = await agent.RunAsync(
      "What's the weather?",
      session,
      new ChatClientAgentRunOptions 
      { 
          ChatOptions = new ChatOptions { MaxOutputTokens = 1000 }
      }
  );

  Console.WriteLine(result.Content);


