    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    [Description("Searches the web for a query and returns relevant results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
            var html = await Http.GetStringAsync(url);

            // Extract text snippets from the HTML results
            var results = ParseSnippets(html);
            return results.Length > 0
                ? $"Search results for \"{query}\":\n{results}"
                : $"No results found for \"{query}\".";
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static string ParseSnippets(string html)
    {
        var snippets = new List<string>();
        // DuckDuckGo Lite returns results in <td> tags with class "result-snippet"
        var searchArea = html;
        var idx = 0;
        while (snippets.Count < 5)
        {
            var snippetStart = searchArea.IndexOf("result-snippet", idx, StringComparison.Ordinal);
            if (snippetStart < 0)
                break;

            var tdStart = searchArea.IndexOf('>', snippetStart);
            if (tdStart < 0) break;

            var tdEnd = searchArea.IndexOf("</td>", tdStart, StringComparison.OrdinalIgnoreCase);
            if (tdEnd < 0) break;

            var raw = searchArea[(tdStart + 1)..tdEnd].Trim();
            var text = StripHtml(raw);
            if (text.Length > 20)
                snippets.Add($"- {text}");

            idx = tdEnd + 5;
        }

        return string.Join('\n', snippets);
    }

    private static string StripHtml(string html)
    {
        var result = System.Text.RegularExpressions.Regex.Replace(html, "<[^>]+>", " ");
        result = WebUtility.HtmlDecode(result);
        return System.Text.RegularExpressions.Regex.Replace(result, @"\s+", " ").Trim();
    }
}

