using System.ComponentModel;
using System.Net;
using System.Text.RegularExpressions;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Logging ---
using var loggerFactory = LoggerFactory.Create(b =>
    b.AddSimpleConsole(o => { o.SingleLine = true; })
     .SetMinimumLevel(LogLevel.Warning));

// --- Chat client (MEAI abstraction over OpenAI) ---
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .AsChatClient(modelId);

// --- Tools ---
var notepad = new Notepad();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        WebSearchTool.SearchAsync,
        nameof(WebSearchTool.SearchAsync),
        "Searches the web for the given query and returns a summary of the top results. " +
        "Use this to gather information about a topic."),

    AIFunctionFactory.Create(
        notepad.AddNote,
        nameof(notepad.AddNote),
        "Saves an important finding as a note. Call this for every key fact you discover."),

    AIFunctionFactory.Create(
        notepad.GetNotes,
        nameof(notepad.GetNotes),
        "Returns all notes taken so far. Use before writing the final summary."),
};

// --- Agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic you must:
        1. Search the web multiple times with varied queries to gather broad information.
        2. Save every key finding as a note using the AddNote tool.
        3. After gathering enough information, retrieve all notes with GetNotes.
        4. Produce a well-structured final summary with sections and references.
        Be thorough — make at least 3 different searches before summarizing.
        """,
    name: "ResearchAgent",
    description: "Researches a topic using web search and note-taking tools.",
    tools: tools,
    loggerFactory: loggerFactory);

// --- Session ---
var session = await agent.CreateSessionAsync();

// --- Run options ---
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (GPT-4o-mini)   ║");
Console.WriteLine("║  Type a topic to research, or 'exit'.    ║");
Console.WriteLine("╚══════════════════════════════════════════╝");

while (true)
{
    Console.Write("\n🔍 Topic: ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.Clear();
    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    try
    {
        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic thoroughly: {topic}",
            session,
            runOptions))
        {
            Console.Write(update.Text);
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }
}

Console.WriteLine("Goodbye!");

// ────────────────────────────────────────────────────────────
// Tools
// ────────────────────────────────────────────────────────────

/// <summary>Simulates web search by fetching real pages via DuckDuckGo Lite.</summary>
static partial class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    [Description("Searches the web for a query and returns relevant results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = ParseSnippets(html);
            return results.Length > 0
                ? $"Search results for \"{query}\":\n{results}"
                : $"No results found for \"{query}\".";
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static string ParseSnippets(string html)
    {
        var snippets = new List<string>();
        var idx = 0;
        while (snippets.Count < 5)
        {
            var snippetStart = html.IndexOf("result-snippet", idx, StringComparison.Ordinal);
            if (snippetStart < 0)
                break;

            var tdStart = html.IndexOf('>', snippetStart);
            if (tdStart < 0) break;

            var tdEnd = html.IndexOf("</td>", tdStart, StringComparison.OrdinalIgnoreCase);
            if (tdEnd < 0) break;

            var raw = html[(tdStart + 1)..tdEnd].Trim();
            var text = StripHtml(raw);
            if (text.Length > 20)
                snippets.Add($"- {text}");

            idx = tdEnd + 5;
        }

        return string.Join('\n', snippets);
    }

    private static string StripHtml(string html)
    {
        var result = HtmlTagRegex().Replace(html, " ");
        result = WebUtility.HtmlDecode(result);
        return WhitespaceRegex().Replace(result, " ").Trim();
    }

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex HtmlTagRegex();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespaceRegex();
}

/// <summary>In-memory notepad for the agent to store research findings.</summary>
sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Saves a research finding as a note.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Returns all notes taken so far.")]
    public string GetNotes()
    {
        return _notes.Count == 0
            ? "No notes yet."
            : string.Join('\n', _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    public void Clear() => _notes.Clear();
}
ENDCS

