using System.ComponentModel;
using System.Net;
using System.Text.RegularExpressions;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Logging ---
using var loggerFactory = LoggerFactory.Create(b =>
    b.AddSimpleConsole(o => { o.SingleLine = true; })
     .SetMinimumLevel(LogLevel.Warning));

// --- Chat client (MEAI abstraction over OpenAI) ---
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .AsChatClient(modelId);

// --- Tools ---
var notepad = new Notepad();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        WebSearchTool.SearchAsync,
        nameof(WebSearchTool.SearchAsync),
        "Searches the web for the given query and returns a summary of the top results. " +
        "Use this to gather information about a topic."),

    AIFunctionFactory.Create(
        notepad.AddNote,
        nameof(notepad.AddNote),
        "Saves an important finding as a note. Call this for every key fact you discover."),

    AIFunctionFactory.Create(
        notepad.GetNotes,
        nameof(notepad.GetNotes),
        "Returns all notes taken so far. Use before writing the final summary."),
};

// --- Agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic you must:
        1. Search the web multiple times with varied queries to gather broad information.
        2. Save every key finding as a note using the AddNote tool.
        3. After gathering enough information, retrieve all notes with GetNotes.
        4. Produce a well-structured final summary with sections and references.
        Be thorough — make at least 3 different searches before summarizing.
        """,
    name: "ResearchAgent",
    description: "Researches a topic using web search and note-taking tools.",
    tools: tools,
    loggerFactory: loggerFactory);

// --- Session ---
var session = await agent.CreateSessionAsync();

// --- Run options ---
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (GPT-4o-mini)   ║");
Console.WriteLine("║  Type a topic to research, or 'exit'.    ║");
Console.WriteLine("╚══════════════════════════════════════════╝");

while (true)
{
    Console.Write("\n🔍 Topic: ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.Clear();
    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    try
    {
        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic thoroughly: {topic}",
            session,
            runOptions))
        {
            Console.Write(update.Text);
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }
}

Console.WriteLine("Goodbye!");

